REVIEW_SHA=PROFILE["review_sha256"]
SOURCE_ID=PROFILE["source_id"]
SOURCE_SHA=PROFILE["source_sha256"]
APPROVED=PROFILE["approved"]
PAGES=PROFILE["pages"]
REQUIRED_LIMITS={"selected_page_secondary_book_statement_only","no_full_book_review_claim","no_current_specimen_measurement_or_truth_claim","no_primary_property_replacement","no_primary_property_or_catalog_formula_replacement","no_model_score_or_training_use"}

def valid_book(book):
 expected=PROFILE['book']
 return all(canonical_sha(book.get(k))==canonical_sha(v) for k,v in expected.items()) and not any(k in book for k in ('isbn','ISBN','publisher','edition','bibliography_review'))

def validate_row(row):
 review=row.get('review',{});cid=review.get('approved_candidate_id');fixed=APPROVED.get(cid)
 need(fixed is not None and row.get('source_id')==SOURCE_ID and review.get('root_record_sha256')==REVIEW_SHA and review.get('source_book_sha256')==SOURCE_SHA,'exact Chinese56 source/Root/approved56 identity required')
 need([row.get('catalog_id'),row.get('field'),row.get('quantity_kind'),row.get('pdf_page_1based'),row.get('formula_display'),review.get('proposal_field_sha256')]==fixed[:6],'approved candidate species/field/formula binding required')
 need(row.get('value')==fixed[7] and canonical_sha(row.get('conditions'))==canonical_sha(fixed[6]),'exact approved narrative and source conditions required')
 need(row.get('unit') is row.get('hardness_scale') is None and REQUIRED_LIMITS<=set(row.get('limits',[])),'secondary Chinese source units and limits required')
 need(not {'Root_approval_pending','no_App_import','short_secondary_book_candidate_only'}&set(row['limits']),'pending candidate flags cannot replace final approval')
 conditions=row.get('conditions');need(isinstance(conditions,list) and all(isinstance(x,str) and len(x)<=200 for x in conditions),'literal source conditions required')
 field=row['field']
 if field=='formula':need(isinstance(row.get('formula_display'),str) and len(row['formula_display'])<=100,'approved formula requires separate literal display')
 else:need('formula_display' not in row,'nonformula statement cannot carry formula display')
 if field=='occurrence':need({'book_reported_location_or_occurrence_not_current_specimen_origin','not_complete_global_distribution','source_unspecified_location_words_preserved'}<=set(conditions),'historical book locality is not specimen origin or complete distribution')
 if field=='cleavage':need('only_reported_plane_family_not_a_complete_cleavage_inventory' in conditions,'{100} is not a complete cleavage inventory')
 pages=row.get('source_pages');need(isinstance(pages,list) and len(pages)==1 and isinstance(pages[0],dict),'one exact public source page required')
 p=pages[0];need(set(p)=={'pdf_page_1based','printed_page','render_sha256'} and type(p['pdf_page_1based']) is int and PAGES.get(str(p['pdf_page_1based']))=={k:p[k] for k in ('printed_page','render_sha256')},'exact selected four-page/render identity required')
 need(p['pdf_page_1based']==row['pdf_page_1based'] and p['printed_page']==row['printed_page'] and review.get('source_evidence_sha256')==canonical_sha(pages),'source locator proof required')
